import {readFile,writeFile,appendFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
const prefix='artifacts/hancom-final-fence-20261007',observedAt=new Date().toISOString();
const report=`# Hancom 최종 발행 경계 보강\n\n관측: ${observedAt}\n\n기존 경로는 beforePublish 검사 뒤 manifest 작성과 임시 진단 파일 정리를 await하고, 그 이후 권한·취소·원본·목적지를 재검사하지 않고 렌더 디렉터리를 발행했다. 실제 발행 직전에 현재 권한을 다시 검사하고, 원본 SHA와 목적지 존재·취소를 재확인하도록 수정했다. 마지막 검사부터 rename까지 JS 비동기 양보를 제거했다.\n\n검증: 23/23 통과, 실패·건너뜀 0. 신규 7건은 실제 임시 파일을 사용하는 권한 철회·취소·원본 변경·목적지 경합·정상 발행 검사다. 기존 Hancom PDF/페이지/구조 자료 독립 재검증과 실제 Python HWPX 생성 검사도 포함한다. build 및 Core 계약 게이트 exit 0. 이번에는 새 Hancom COM 렌더를 수행하지 않았으며 원래 HWP/HWPX 생성 전체의 SQL 효과계약은 아직 미연결이다.\n\nOS의 다른 프로세스가 동기 검사와 rename 사이에 변경하는 경쟁까지 원자적으로 해결했다는 뜻은 아니다. 무덮어쓰기 다중 산출물 발행과 부모 제어 staging은 다음 작업이다. 운영 서비스·설치 EXE 활성화 없음. 비용 미측정. 공식 인수 60/100 유지.\n\n연구 감시·장부 sync/status exit 0. 감시 6곳 중 OpenAI 3곳 changed, 나머지 unchanged. 공식 원문을 다시 열었으나 이번 구현에 새 SDK나 모델을 설치하지 않았다. 변화 감지만으로 새 출시나 성능 개선을 주장하지 않는다.\n\n공식 근거: [Node fs](https://nodejs.org/api/fs.html), [Agents API](https://developers.openai.com/api/docs/guides/agents-api/overview), [SDK](https://developers.openai.com/api/docs/guides/agents/sdk), [변경 기록](https://developers.openai.com/api/docs/changelog).\n`;
await writeFile(prefix+'-report.md',report,{flag:'wx'});
const paths=['apps/pc-agent/src/adapters/hwpx/native-pdf-renderer.js','tests/hancom-publication-fence.test.js'];
await writeFile(prefix+'-source.json',JSON.stringify(await Promise.all(paths.map(async path=>({path,sha256:createHash('sha256').update(await readFile(path)).digest('hex')}))),null,2),{flag:'wx'});
await writeFile(prefix+'-attempt.json',JSON.stringify({id:'hancom-final-fence-20261007',candidateId:'agent-platform-observed-scenario-status',kind:'workflow-test',reportedOutcome:'passed',observedAt,hypothesis:'발행 직전 현재 권한과 취소·원본·목적지를 재검사하면 비동기 정리 동안 발생한 변경의 잘못된 발행을 차단한다.',lesson:'앞선 권한 검사는 비동기 파일 정리 이후의 발행 권한을 보장하지 않는다.',limitations:'7 실제 임시파일 경계검사와 총23 회귀. 이번 COM 새 렌더 미실행, SQL 효과/OS 원자적 경합/운영 활성화 미완료. 비용 미측정·공식60/100.',evidencePaths:[prefix+'-report.md',prefix+'-source.json',prefix+'-final.txt',prefix+'-build.txt',prefix+'-contract.txt']},null,2),{flag:'wx'});
await appendFile('docs/execution-to-100.md',`\n최신 ${prefix}-report.md: Hancom 렌더 최종 권한/취소/원본/목적지 재검사·23/23 회귀/build/contract. 공식60·새COM/운영활성화0. 다음 HWP/HWPX 부모staging/전체manifest/SQL 효과 연결.\n`);
